// Loads the GLB assets.
// - Characters and firearms: CC0 models by Quaternius (via poly.pizza), see README credits.
//   Every firearm is normalized on load (barrel → -Z, metric length, grip at the origin, "Muzzle" node)
//   so gameplay code never depends on how the source file was authored.
// - C4 and grenades: generated by tools/build-models.mjs (models/weapons.glb).
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import * as SkeletonUtils from 'three/examples/jsm/utils/SkeletonUtils.js';
import { FINISHES } from '../config/weapons';
import type { Look } from '../room/RoomState';

export type CharKind = 'swat' | 'woman';

export interface CharacterInstance {
  kind: CharKind;
  root: THREE.Group;
  mixer: THREE.AnimationMixer;
  actions: Map<string, THREE.AnimationAction>;
  materials: { jacket: THREE.MeshStandardMaterial; visor: THREE.MeshStandardMaterial | null; accent: THREE.MeshStandardMaterial | null };
  hand: THREE.Object3D;
  head: THREE.Object3D;
  legs: { upperL: THREE.Object3D | null; upperR: THREE.Object3D | null; lowerL: THREE.Object3D | null; lowerR: THREE.Object3D | null; hips: THREE.Object3D | null };
}

interface GunSpec { file: string; rot: THREE.Euler; length: number }
const GUNS: Record<string, GunSpec> = {
  pistol: { file: 'pistol', rot: new THREE.Euler(0, 0, 0), length: 0.24 },
  longpistol: { file: 'longpistol', rot: new THREE.Euler(0, 0, 0), length: 0.3 },
  smg: { file: 'smg', rot: new THREE.Euler(0, Math.PI / 2, 0), length: 0.44 },
  rifle: { file: 'rifle', rot: new THREE.Euler(0, Math.PI / 2, 0), length: 0.84 },
  bullpup: { file: 'bullpup', rot: new THREE.Euler(0, Math.PI / 2, 0), length: 0.74 },
  sniper: { file: 'sniper', rot: new THREE.Euler(0, Math.PI / 2, 0), length: 1.1 },
  shotgun: { file: 'shotgun', rot: new THREE.Euler(0, Math.PI / 2, 0), length: 0.95 },
  knife: { file: 'knife', rot: new THREE.Euler(-Math.PI / 2, 0, 0), length: 0.3 },
};
/** Materials recoloured by a weapon finish (the main body colours of the Quaternius guns). */
const FINISH_MATS = /^(Main|Main2|MainDark|Metal|DarkMetal|Grey|Handle|Black)$/;

class AssetStore {
  private chars = new Map<CharKind, { scene: THREE.Object3D; clips: THREE.AnimationClip[] }>();
  private weapons = new Map<string, THREE.Object3D>();
  private finishCache = new Map<string, THREE.Material>();
  loaded = false;

  async load(onProgress: (p: number) => void): Promise<void> {
    const loader = new GLTFLoader();
    const base = import.meta.env.BASE_URL;
    const files = ['models/weapons.glb', 'models/cc0/swat.glb', 'models/cc0/woman.glb', ...Object.values(GUNS).map((g) => `models/cc0/${g.file}.glb`)];
    let done = 0;
    const results = await Promise.all(files.map((f) => loader.loadAsync(base + f).then((g) => { onProgress(++done / files.length); return g; })));
    const [wpn, swat, woman, ...guns] = results;
    for (const child of [...wpn.scene.children]) this.weapons.set(child.name, child);
    this.chars.set('swat', { scene: swat.scene, clips: swat.animations });
    this.chars.set('woman', { scene: woman.scene, clips: woman.animations });
    for (const s of [swat.scene, woman.scene]) s.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.castShadow = true;
      m.receiveShadow = true;
      m.frustumCulled = false;
    });
    Object.keys(GUNS).forEach((id, i) => this.weapons.set(id, this.normalizeGun(guns[i].scene, GUNS[id])));
    this.loaded = true;
  }

  private normalizeGun(src: THREE.Object3D, spec: GunSpec): THREE.Object3D {
    const inner = new THREE.Group();
    inner.add(src);
    src.updateMatrixWorld(true);
    inner.rotation.copy(spec.rot);
    inner.updateMatrixWorld(true);
    let box = new THREE.Box3().setFromObject(inner);
    const size = box.getSize(new THREE.Vector3());
    const k = spec.length / Math.max(size.x, size.y, size.z);
    inner.scale.setScalar(k);
    inner.updateMatrixWorld(true);
    box = new THREE.Box3().setFromObject(inner);
    const len = box.max.z - box.min.z;
    const h = box.max.y - box.min.y;
    // grip at the origin: muzzle forward (-Z), rear behind, sights ~6 cm above the hand
    const top = 0.05 + 0.06 * len;
    inner.position.set(-(box.min.x + box.max.x) / 2, top - box.max.y, -box.max.z + len * 0.36);
    const out = new THREE.Group();
    out.add(inner);
    out.updateMatrixWorld(true);
    box = new THREE.Box3().setFromObject(out);
    const muzzle = new THREE.Object3D();
    muzzle.name = 'Muzzle';
    muzzle.position.set(0, box.max.y - h * 0.3, box.min.z);
    out.add(muzzle);
    out.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.castShadow = true;
      const mat = m.material as THREE.MeshStandardMaterial;
      if (mat?.isMeshStandardMaterial) { mat.roughness = Math.min(mat.roughness, 0.55); mat.metalness = Math.max(mat.metalness, 0.35); }
    });
    return out;
  }

  character(look: Look, kind: CharKind = 'swat'): CharacterInstance {
    const t = this.chars.get(kind)!;
    const root = SkeletonUtils.clone(t.scene) as THREE.Group;
    const clone = new Map<THREE.Material, THREE.MeshStandardMaterial>();
    const byName = new Map<string, THREE.MeshStandardMaterial>();
    root.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      const fix = (mat: THREE.Material) => {
        let c = clone.get(mat);
        if (!c) { c = (mat as THREE.MeshStandardMaterial).clone(); c.roughness = Math.min(0.8, c.roughness); clone.set(mat, c); byName.set(c.name, c); }
        return c;
      };
      m.material = Array.isArray(m.material) ? m.material.map(fix) : fix(m.material);
    });
    const jacket = byName.get(kind === 'swat' ? 'Swat' : 'White') ?? [...byName.values()][0];
    const visor = byName.get('Visor') ?? null;
    const accent = byName.get(kind === 'swat' ? 'Swat_Black' : 'Orange') ?? null;
    if (visor) { visor.emissiveIntensity = 2.4; visor.roughness = 0.15; visor.metalness = 0.6; }
    const mixer = new THREE.AnimationMixer(root);
    const actions = new Map<string, THREE.AnimationAction>();
    for (const clip of t.clips) actions.set(clip.name.replace(/^.*\|/, ''), mixer.clipAction(clip));
    // GLTFLoader sanitizes node names ("Wrist.R" → "WristR")
    const bone = (n: string) => root.getObjectByName(n.replace(/[.:\/[\]]/g, '')) ?? root.getObjectByName(n) ?? null;
    const inst: CharacterInstance = {
      kind, root, mixer, actions, materials: { jacket, visor, accent },
      hand: bone('Wrist.R') ?? bone('LowerArm.R') ?? root, head: bone('Head') ?? root,
      legs: { upperL: bone('UpperLeg.L'), upperR: bone('UpperLeg.R'), lowerL: bone('LowerLeg.L'), lowerR: bone('LowerLeg.R'), hips: bone('Hips') },
    };
    applyLook(inst, look);
    return inst;
  }

  weapon(model: string, finishId = 'stock'): THREE.Object3D {
    const src = this.weapons.get(model);
    if (!src) return new THREE.Object3D();
    const w = src.clone(true);
    const finish = FINISHES.find((f) => f.id === finishId) ?? FINISHES[0];
    const procedural = !(model in GUNS);
    w.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.castShadow = true;
      if (finish.id === 'stock') return;
      const recolor = (mat: THREE.MeshStandardMaterial) => {
        const target = procedural ? mat.name === 'Polymer' || mat.name.startsWith('Accent') : FINISH_MATS.test(mat.name);
        if (!target) return mat;
        const key = `${finish.id}:${model}:${mat.name}`;
        let c = this.finishCache.get(key) as THREE.MeshStandardMaterial | undefined;
        if (!c) {
          c = mat.clone();
          if (mat.name.startsWith('Accent')) c.emissive.setHex(finish.accent);
          else {
            const base = new THREE.Color(finish.color);
            // keep the authored light/dark contrast between parts
            const l = mat.color.getHSL({ h: 0, s: 0, l: 0 }).l;
            c.color.copy(base).multiplyScalar(0.55 + l * 0.9);
            c.emissive.setHex(finish.accent);
            c.emissiveIntensity = /Dark|Black/.test(mat.name) ? 0.0 : 0.08;
            if (finish.id === 'chrome') { c.metalness = 1; c.roughness = 0.12; }
          }
          this.finishCache.set(key, c);
        }
        return c;
      };
      m.material = Array.isArray(m.material) ? m.material.map((x) => recolor(x as THREE.MeshStandardMaterial)) : recolor(m.material as THREE.MeshStandardMaterial);
    });
    return w;
  }
}

export function applyLook(c: CharacterInstance, look: Look): void {
  c.materials.jacket.color.setHex(look.jacket).lerp(new THREE.Color(0x8a93a6), 0.25);
  if (c.materials.visor) c.materials.visor.emissive.setHex(look.visor);
  if (c.materials.accent) { c.materials.accent.emissive.setHex(look.trim); c.materials.accent.emissiveIntensity = 0.12; }
}

export const Assets = new AssetStore();
